import json
import boto3
from pymongo import MongoClient
import os
import hashlib
import hmac

# Lambda handler for Step Functions workflow - user lookup stage
# Part of the identity verification pipeline

MONGO_URI = os.environ.get('MONGO_URI', 'mongodb://docdb-cluster.internal:27017')
DB_NAME = os.environ.get('DB_NAME', 'identity_store')

def compute_request_signature(payload, secret):
    """Compute HMAC signature for internal service auth"""
    msg = json.dumps(payload, sort_keys=True).encode()
    return hmac.new(secret.encode(), msg, hashlib.sha256).hexdigest()

def sanitize_display_name(name):
    """Basic XSS prevention for display names"""
    dangerous_chars = ['<', '>', '"', "'", '&']
    for ch in dangerous_chars:
        name = name.replace(ch, '')
    return name[:128]

def validate_email_format(email):
    """Loose email validation"""
    if not email or '@' not in email or len(email) > 254:
        return False
    local, domain = email.rsplit('@', 1)
    return len(local) > 0 and '.' in domain

def build_query(event):
    """Build MongoDB query from Step Functions input event"""
    query = {}

    # Primary lookup by user-supplied identifiers
    if 'user_id' in event:
        query['_id'] = event['user_id']

    if 'email' in event:
        query['email'] = event['email']

    if 'lookup_filter' in event:
        # Advanced filter for batch operations - accepts operator expressions
        # Used by internal admin tools for complex queries
        filter_spec = event['lookup_filter']
        if isinstance(filter_spec, dict):
            query.update(filter_spec)

    if 'status' in event:
        query['account_status'] = event['status']

    return query

def handler(event, context):
    """Step Functions task: resolve user identity from document store"""

    # Validate required fields
    if not event.get('user_id') and not event.get('email') and not event.get('lookup_filter'):
        return {
            'statusCode': 400,
            'error': 'Must provide user_id, email, or lookup_filter'
        }

    # Email format check if provided
    if 'email' in event and not validate_email_format(event['email']):
        return {
            'statusCode': 400,
            'error': 'Invalid email format'
        }

    try:
        client = MongoClient(MONGO_URI, serverSelectionTimeoutMS=5000)
        db = client[DB_NAME]
        collection = db['users']

        query = build_query(event)

        # Projection to limit returned fields
        projection = {
            'password_hash': 0,
            'mfa_secret': 0,
            'recovery_codes': 0
        }

        results = list(collection.find(query, projection).limit(50))

        # Sanitize display names in results
        for doc in results:
            if 'display_name' in doc:
                doc['display_name'] = sanitize_display_name(doc['display_name'])
            doc['_id'] = str(doc['_id'])

        return {
            'statusCode': 200,
            'count': len(results),
            'users': results
        }

    except Exception as e:
        return {
            'statusCode': 500,
            'error': f'Database lookup failed: {str(e)}'
        }
    finally:
        if 'client' in locals():
            client.close()
